LOADER = "load(':%s', 'VALUE')\nexports_files(['private/real.bzl'])\ngenrule(name = 'out', outs = ['out.txt'], cmd = 'echo %%s > $@' %% VALUE)\n"

def _gen(ctx):
    k = ctx.attr.kind
    ctx.file("private/real.bzl", "VALUE = 'in_repo'\n")
    if k == "relative":
        ctx.symlink("private/real.bzl", "cfg.bzl")
    elif k == "absolute_in_repo":
        ctx.symlink(ctx.path("private/real.bzl"), "cfg.bzl")
    elif k == "dangling":
        ctx.symlink("nothere.bzl", "cfg.bzl")
    elif k == "cross_external":
        ctx.symlink(Label("@src//:real.bzl"), "cfg.bzl")
    elif k == "cross_external_path":
        ctx.symlink(ctx.path(Label("@src//:real.bzl")), "cfg.bzl")
    elif k == "cross_main":
        ctx.symlink(Label("//tools:config.bzl"), "cfg.bzl")
    elif k == "escape_relative":
        ctx.symlink("../../outside_gen.bzl", "cfg.bzl")
    elif k == "dir_link":
        ctx.symlink("private", "pdir")
    ctx.file("BUILD.bazel", LOADER % ("pdir/real.bzl" if k == "dir_link" else "cfg.bzl"))

gen = repository_rule(_gen, attrs = {"kind": attr.string()})

